using System;using System.IO;using System.IO.Compression;using System.Diagnostics;using System.Security.Cryptography;using System.Windows.Forms;class ToolSetup{[STAThread]static void Main(){Application.EnableVisualStyles();try{string name="__PRODUCT__",version="__VERSION__",exe="__EXE__";string target=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),name,version);string marker=Path.Combine(target,".complete");if(!File.Exists(marker)){string staging=target+".extract-"+Guid.NewGuid().ToString("N");Directory.CreateDirectory(staging);string zip=Path.Combine(staging,"payload.zip");try{using(FileStream input=File.OpenRead(Application.ExecutablePath)){input.Seek(-48,SeekOrigin.End);byte[] trailer=new byte[48];input.Read(trailer,0,48);if(System.Text.Encoding.ASCII.GetString(trailer,0,8)!="PLTOOL01")throw new Exception("安装文件不完整");long size=BitConverter.ToInt64(trailer,8);if(size<=0||size>input.Length-48)throw new Exception("安装长度无效");input.Seek(-48-size,SeekOrigin.End);using(FileStream output=File.Create(zip)){byte[] buffer=new byte[1048576];long left=size;while(left>0){int n=input.Read(buffer,0,(int)Math.Min(buffer.Length,left));if(n==0)throw new Exception("安装文件截断");output.Write(buffer,0,n);left-=n;}}using(SHA256 sha=SHA256.Create())using(FileStream data=File.OpenRead(zip)){byte[] hash=sha.ComputeHash(data);for(int i=0;i<32;i++)if(hash[i]!=trailer[16+i])throw new Exception("安装文件校验失败");}}ZipFile.ExtractToDirectory(zip,staging);File.Delete(zip);if(Directory.Exists(target))throw new Exception("此版本目录已存在但安装不完整，请关闭工具后删除该目录再试："+target);Directory.Move(staging,target);File.WriteAllText(marker,version);}finally{if(Directory.Exists(staging))Directory.Delete(staging,true);}}string program=Path.Combine(target,exe);if(!File.Exists(program))throw new Exception("程序文件缺失");try{string shortcut=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.DesktopDirectory),name+".lnk");Type t=Type.GetTypeFromProgID("WScript.Shell");dynamic shell=Activator.CreateInstance(t);dynamic link=shell.CreateShortcut(shortcut);link.TargetPath=program;link.WorkingDirectory=target;link.Save();}catch{}Process.Start(new ProcessStartInfo(program){WorkingDirectory=target,UseShellExecute=true});}catch(Exception e){MessageBox.Show(e.Message,"PSD Lingo 工具安装",MessageBoxButtons.OK,MessageBoxIcon.Error);}}}